android.extraProguardRules:
# Expo Kotlin records (SecureStore & friends) are read by reflection: keep them whole.
-keep class expo.modules.kotlin.records.** { *; }
# kn-android-polish legacy native modules: keep @ReactMethod bridge targets and the package.
-keep class dev.kinetic.writer.MaterialYouModule { *; }
-keep class dev.kinetic.writer.SaveFileModule { *; }
-keep class dev.kinetic.writer.MaterialYouPackage { *; }
-keepclassmembers class * { @com.facebook.react.bridge.ReactMethod <methods>; }
